VAR_INPUT
    recipe   : ARRAY[1..8] OF ST_Recipe;
    selSlot  : INT;
    loadCmd  : BOOL;
    running  : BOOL;
END_VAR
VAR_OUTPUT
    valid    : BOOL;
    loadedID : INT;
END_VAR
VAR
    prevLoadCmd  : BOOL;
    curLoadedID : INT;
    curValid    : BOOL;
    curRecipe   : ST_Recipe;
END_VAR

// Detect rising edge of load command
IF loadCmd AND NOT prevLoadCmd THEN
    // Rising edge – process only when not running
    IF NOT running THEN
        // Slot bounds check
        IF (selSlot >= 1) AND (selSlot <= 8) THEN
            curRecipe := recipe[selSlot];
            // Validation: non‑empty slot, totalRatio in 99..101, temperature in 30..180
