               (curRecipe.totalRatio >= 99.0) AND (curRecipe.totalRatio <= 101.0) AND
               (curRecipe.temperature >= 30.0) AND (curRecipe.temperature <= 180.0) THEN
                curLoadedID := curRecipe.recipeID;
                curValid    := TRUE;
            ELSE
                curLoadedID := 0;
                curValid    := FALSE;
            END_IF
        ELSE
            // Out‑of‑range slot – illegal
            curLoadedID := 0;
            curValid    := FALSE;
        END_IF
    END_IF
END_IF

// Drive outputs
loadedID := curLoadedID;
valid    := curValid;

// Update edge‑detection memory
prevLoadCmd := loadCmd;
END_FUNCTION_BLOCK
